import{_ as t,o as i,c as a,l as s,t as o,N as r}from"./chunks/framework.Gjrf2Eoj.js";const b=JSON.parse('{"title":"git-credential-store | x-cmd man (git man1) | Helper to store credentials on disk","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-credential-store - Helper to store credentials on disk","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-credential-store | x-cmd man (git man1) | Helper to store credentials on disk"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-credential-store - Helper to store credentials on disk"}]]},"headers":[],"params":{"isMan":true,"man":"git-credential-store","category":"git man1","desc":"Helper to store credentials on disk"},"relativePath":"git/man1/git-credential-store.md","filePath":"git/man1/git-credential-store.md"}'),n={name:"git/man1/git-credential-store.md"},l={class:"visually-hidden"},d=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-credential-store - Helper to store credentials on disk</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> credential.helper</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;store [&lt;options&gt;]&#39;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><blockquote><p><br> &gt; <strong>Note</strong></p><p><br> &gt; Using this helper will store your passwords unencrypted on disk, protected only by filesystem permissions. If this is not an acceptable security tradeoff, try <strong>git-credential-cache</strong>(1), or find a helper that integrates with secure storage provided by your operating system.</p></blockquote><p>This command stores credentials indefinitely on disk for use by future Git programs.</p><p>You probably don&#39;t want to invoke this command directly; it is meant to be used as a credential helper by other parts of git. See <strong>gitcredentials</strong>(7) or <strong>EXAMPLES</strong> below.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--file=&lt;path&gt;</p><blockquote><p>Use <strong>&lt;path&gt;</strong> to lookup and store credentials. The file will have its filesystem permissions set to prevent other users on the system from reading it, but will not be encrypted or otherwise protected. If not specified, credentials will be searched for from <strong>~/.git-credentials</strong> and <strong>$XDG_CONFIG_HOME/git/credentials</strong>, and credentials will be written to <strong>~/.git-credentials</strong> if it exists, or <strong>$XDG_CONFIG_HOME/git/credentials</strong> if it exists and the former does not. See also the section called &quot;FILES&quot;.</p></blockquote><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><p>If not set explicitly with <strong>--file</strong>, there are two files where git-credential-store will search for credentials in order of precedence:</p><p>~/.git-credentials</p><blockquote><p>User-specific credentials file.</p></blockquote><p>$XDG_CONFIG_HOME/git/credentials</p><blockquote><p>Second user-specific credentials file. If <em>$XDG_CONFIG_HOME</em> is not set or empty, <strong>$HOME/.config/git/credentials</strong> will be used. Any credentials stored in this file will not be used if <strong>~/.git-credentials</strong> has a matching credential as well. It is a good idea not to create this file if you sometimes use older versions of Git that do not support it.</p></blockquote><p>For credential lookups, the files are read in the order given above, with the first matching credential found taking precedence over credentials found in files further down the list.</p><p>Credential storage will by default write to the first existing file in the list. If none of these files exist, <strong>~/.git-credentials</strong> will be created and written to.</p><p>When erasing credentials, matching credentials will be erased from all files.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>The point of this helper is to reduce the number of times you must type your username or password. For example:</p><blockquote><pre><code>$ git config credential.helper store
$ git push http://example.com/repo.git
Username: &lt;type your username&gt;
Password: &lt;type your password&gt;

[several days later]
$ git push http://example.com/repo.git
[your credentials are used automatically]
</code></pre></blockquote><h2 id="storage-format" tabindex="-1">STORAGE FORMAT <a class="header-anchor" href="#storage-format" aria-label="Permalink to &quot;STORAGE FORMAT&quot;">​</a></h2><p>The <strong>.git-credentials</strong> file is stored in plaintext. Each credential is stored on its own line as a URL like:</p><blockquote><pre><code>https://user:pass@example.com
</code></pre></blockquote><p>No other kinds of lines (e.g. empty lines or comment lines) are allowed in the file, even though some may be silently ignored. Do not view or edit the file with editors.</p><p>When Git needs authentication for a particular URL context, credential-store will consider that context a pattern to match against each entry in the credentials file. If the protocol, hostname, and username (if we already have one) match, then the password is returned to Git. See the discussion of configuration in <strong>gitcredentials</strong>(7) for more information.</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,30);function c(e,p,h,g,m,u){return i(),a("div",null,[s("h1",l,o(e.$params.man),1),d])}const k=t(n,[["render",c]]);export{b as __pageData,k as default};
